mod solution;

fn main() {
    let cases = [
    (r#"text=ababcabcabababd pattern=ababd"#, r#"10"#),
    (r#"text=aaaa pattern=aa"#, r#"0"#),
    (r#"
text=aaaa pattern=aa
"#, r#"0"#),
    (r#"  
text=ababcabcabababd pattern=ababd
  "#, r#"10"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS kmp");
}
